"use strict";(globalThis.webpackChunkweb||=[]).push([[2810],{2810(e){e.exports=JSON.parse('{"group":"macroFunctions","count":65,"entries":{"%BQUOTE":{"help":"[Syntax: %BQUOTE (character string | text expression)]\\n    \\nMask special characters and mnemonic operators in a resolved value at macro execution."},"%DEQUOTE":{"help":"Removes matching quotation marks from a character string that begins with a quotation mark, \\nand deletes all characters to the right of the closing quotation mark."},"%NRBQUOTE":{"help":"[Syntax: %NRBQUOTE (character string | text expression)]\\n    \\nMask special characters and mnemonic operators in a resolved value at macro execution."},"%EVAL":{"help":"[Syntax: %EVAL (arithmetic or logical expression)]\\n\\nEvaluates arithmetic and logical expressions using integer arithmetic."},"%INDEX":{"help":"[Syntax: %INDEX (source, string)]\\n    \\nReturns the position of the first character of a string."},"%LENGTH":{"help":"[Syntax: %LENGTH (character string | text expression)]\\n\\nReturns the length of a string."},"%QUOTE":{"help":"[Syntax: %QUOTE (character string | text expression)]\\n    \\nMask special characters and mnemonic operators in a resolved value at macro execution.\\nUnmatched quotation marks (\\" \\")  and parentheses ( () )  must be marked with a preceding %."},"%NRQUOTE":{"help":"[Syntax: %NRQUOTE (character string | text expression)]\\n    \\nMask special characters and mnemonic operators in a resolved value at macro execution.\\nUnmatched quotation marks (\\" \\")  and parentheses ( () )  must be marked with a preceding %."},"%SCAN":{"help":"[Syntax: %SCAN(argument, n<, delimiters>)] \\n    \\nSearch for a word that is specified by its position in a string."},"%QSCAN":{"help":"[Syntax: %QSCAN(argument, n<, delimiters>)]\\n\\nMasks special characters and mnemonic operators in its result."},"%STR":{"help":"[Syntax: %STR (character-string)]\\n\\nMask special characters and mnemonic operators in constant text at macro compilation.\\nUnmatched quotation marks (\\" \\")  and parentheses ( () )  must be marked with a preceding %."},"%NRSTR":{"help":"[Syntax: %NRSTR (character-string)]\\n\\nMask special characters and mnemonic operators in constant text at macro compilation.\\nUnmatched quotation marks (\\" \\")  and parentheses ( () )  must be marked with a preceding %."},"%SUBSTR":{"help":"[Syntax: %SUBSTR (argument, position<, length>)] \\n    \\nProduce a substring of a character string."},"%QSUBSTR":{"help":"[Syntax: %QSUBSTR (argument, position<, length>)]\\n\\nProduce a substring of a character string. %QSUBSTR masks special characters and mnemonic \\noperators in its result."},"%SUPERQ":{"help":"[Syntax: %SUPERQ (argument)] \\n    \\nMasks all special characters and mnemonic operators at macro execution but prevents resolution \\nof the value."},"%SYMEXIST":{"help":"[Syntax: %SYMEXIST (argument)]\\n\\nReturns an indication as to whether the named macro variable exists."},"%SYMGLOBL":{"help":"[Syntax: %SYMGLOBL(macro-variable-name)] \\n    \\nReturns an indication as to whether the named macro variable is global in scope."},"%SYMLOCAL":{"help":"[Syntax: %SYMLOCAL(macro-variable-name)]\\n\\nReturns an indication as to whether the named macro variable is local in scope."},"%SYSEVALF":{"help":"[Syntax: %SYSEVALF(expression<, conversion-type>)]\\n\\nEvaluates arithmetic and logical expressions using floating point arithmetic."},"%SYSFUNC":{"help":"[Syntax: %SYSFUNC (function(argument(s))<, format>)] \\n    \\nExecute SAS functions or user-written functions."},"%QSYSFUNC":{"help":"[Syntax: %QSYSFUNC (function(argument(s))<, format>)]\\n\\nExecute SAS functions or user-written functions. Masks special characters and mnemonic operators \\nin its result."},"%SYSGET":{"help":"[Syntax: %SYSGET(environment-variable)]\\n\\nReturns the value of a specified host environment variable."},"%SYSPROD":{"help":"[Syntax: %SYSPROD (product)]\\n\\nReports whether a SAS software product is licensed at the site."},"%UNQUOTE":{"help":"[Syntax: %UNQUOTE (character string | text expression)]\\n\\nUnmasks all special characters and mnemonic operators for a value."},"%UPCASE":{"help":"[Syntax: %UPCASE (character string | text expression)]\\n    \\nConverts characters to uppercase."},"%LOWCASE":{"help":"[Syntax: %LOWCASE (character string | text expression)]\\n\\nConverts characters to lowercase. LOWCASE returns a result without quotation marks, even if the \\nargument has quotation marks."},"%QLOWCASE":{"help":"Syntax: %QLOWCASE(text | text expression)\\n\\nChanges uppercase characters to lowercase and returns a result that masks special \\ncharacters and mnemonic operators."},"%QUPCASE":{"help":"[Syntax: %QUPCASE (character string | text expression)] \\n    \\nConvert characters to uppercase. %QUPCASE masks special characters and mnemonic operators \\nin its result."},"%PUT":{"help":"Returns a value using a specified format."},"%TPLOT":{"help":"The %TPLOT macro creates a triangular plot that graphically displays genetic marker \\ntest results. The plot has colors and shapes representing p-value ranges for tests \\nof the following quantities: linkage disequilibrium between pairs of markers, Hardy-\\nWeinberg equilibrium (HWE) for individual markers, and associations between markers \\nand a dichotomous trait (such as disease status)."},"%SYSMACEXEC":{"help":"Returns an indication of the execution status of a macro.\\n    \\nSyntax: \\n%SYSMACEXEC(macro_name) \\n\\nRequired Argument:\\nmacro_name \\n  the name of a macro or a text expression that yields the name of the macro. \\n\\nDetails:\\nThe %SYSMACEXEC function returns the number 1 if the macro is currently executing. \\nOtherwise, if the macro is not executing, the number 0 is returned."},"%SYSMACEXIST":{"help":"Returns an indication of the existence of a macro definition in the WORK.SASMACR \\ncatalog. Otherwise, the returned value is 0.\\n    \\nSyntax \\n%SYSMACEXIST(macro-name) \\nRequired Argument \\nmacro-name \\nthe name of a macro or a text expression that yields the name of a macro. \\nDetails \\nThe %SYSMACEXIST function returns the number 1 if a definition for the macro exists in the WORK.SASMACR catalog. If there is not a macro definition, the returned value is 0."},"%SYSMEXECDEPTH":{"help":"Returns the nesting depth of macro execution from the point of the call to %SYSMEXECDEPTH.\\n    \\nSyntax:\\n%SYSMEXECDEPTH\\n\\nDetails:\\nTo retrieve the nesting level of the currently executing macro, use the %SYSMEXECDEPTH. \\nThis function returns a number indicating the depth of the macro in nested macro calls. \\n\\nThe following are the %SYSMEXECDEPTH return value descriptions: \\n  0  open code \\n >0  nesting level"},"%SYSMEXECNAME":{"help":"Returns the name of the macro executing at a requested nesting level.\\n    \\nSyntax:\\n%SYSMEXECNAME (n) \\n\\nRequired Argument:\\nn \\n  The nesting level at which you are requesting the macro name. \\n    0 open code \\n    >0 nesting level"},"%CMPRES":{"help":"Syntax: %CMPRES (text | text expression)\\n\\nCompresses multiple blanks and removes leading and trailing blanks."},"%QCMPRES":{"help":"Syntax: %QCMPRES (text | text expression)\\n\\nCompresses multiple blanks and removes leading and trailing blanks.\\n\\n%QCMPRES masks the result so special characters and mnemonic operators are treated \\nas text instead of being interpreted by the macro facility."},"%COMPSTOR":{"help":"Syntax: %COMPSTOR (PATHNAME=SAS-data-library)\\n\\nCompiles macros and stores them in a catalog in a permanent SAS library."},"%DATATYP":{"help":"Syntax:%DATATYP (text | text expression)\\n\\nReturns the data type (numeric or char) of a value."},"%LEFT":{"help":"Syntax: %LEFT(text | text expression)\\n    \\nLeft-aligns an argument by removing leading blanks."},"%QLEFT":{"help":"Syntax: %QLEFT(text | text expression)\\n\\nLeft-aligns an argument by removing leading blanks.\\n\\nQLEFT masks the result so special characters and mnemonic operators are treated as \\ntext instead of being interpreted by the macro facility."},"%SYSRC":{"help":"[Syntax: %SYSRC(character-string)]\\n\\nReturns a value corresponding to an error condition."},"%TRIM":{"help":"Syntax: %TRIM(text | text expression)\\n\\nTrim trailing blanks."},"%QTRIM":{"help":"Syntax: %QTRIM(text | text expression)\\n    \\nTrim trailing blanks. Masks special characters and mnemonic operators."},"%VERIFY":{"help":"Syntax: %VERIFY(source, excerpt)\\n    \\nReturns the position of the first character unique to an expression."},"%DQLOAD":{"help":"Syntax: %DQLOAD(DQLOCALE=(locale1 ...localeN), DQSETUPLOC=`file-specification\', <DQINFO=0 | 1>)\\n    \\nSets system option values and loads locales into memory."},"%DQPUTLOC":{"help":"Syntax: %DQPUTLOC(locale, <SHORT=0 | 1>, <PARSEDEFN=0 | 1)>\\n    \\nDisplays current information on a specified locale in the SAS log."},"%DQUNLOAD":{"help":"Syntax: %DQUNLOAD \\n    \\nUnloads all locales to increase the amount of free memory."},"%KLOWCASE":{"help":"Syntax: %KLOWCASE (text | text expression) \\n\\nChanges uppercase alphabetic characters to their lowercase equivalents. If the argument \\nmight contain a special character or mnemonic operator, listed below, use %QKLOWCAS. \\n\\n%KLOWCASE returns a result without quotation marks, even if the argument has quotation marks. \\n%QKLOWCAS produces a result with the following special characters and mnemonic operators masked \\nso the macro processor interprets them as text instead of as elements of the macro language: \\n\\n  & % \' \\" ( ) + - * / < > = ¬ ^ ~ ; , blank AND OR NOT EQ NE LE LT GE GT IN \\n\\nAutocall macros are included in a SAS library. This library might not be installed at your site \\nor might be a site-specific version. If you cannot access this macro or if you want to find out \\nif the library is a site-specific version, see your on-site SAS support personnel."},"%QKLOWCAS":{"help":"Syntax: %QKLOWCAS (text | text expression) \\n\\nChanges uppercase alphabetic characters to their lowercase equivalents. If the argument \\nmight contain a special character or mnemonic operator, listed below, use %QKLOWCAS. \\n\\n%KLOWCASE returns a result without quotation marks, even if the argument has quotation marks. \\n%QKLOWCAS produces a result with the following special characters and mnemonic operators masked \\nso the macro processor interprets them as text instead of as elements of the macro language: \\n\\n  & % \' \\" ( ) + - * / < > = ¬ ^ ~ ; , blank AND OR NOT EQ NE LE LT GE GT IN \\n\\nAutocall macros are included in a SAS library. This library might not be installed at your site \\nor might be a site-specific version. If you cannot access this macro or if you want to find out \\nif the library is a site-specific version, see your on-site SAS support personnel."},"%KTRIM":{"help":"Syntax: %KTRIM (text | text expression) \\n    \\nTrims trailing blanks. If the argument contains a special character or mnemonic operator, \\nlisted below, use %QKTRIM. \\n\\nQKTRIM produces a result with the following special characters and mnemonic operators masked \\nso the macro processor interprets them as text instead of as elements of the macro language: \\n\\n  & % \' \\" ( ) + - * / < > = ¬ ? ~ ; , # blank AND OR NOT EQ NE LE LT GE GT IN \\n  \\nAutocall macros are included in a SAS library. This library might not be installed at your \\nsite or might be a site-specific version. If you cannot access this macro or if you want to \\nfind out if the library is a site-specific version, see your on-site SAS support personnel."},"%QKTRIM":{"help":"Syntax: %QKTRIM (text | text expression) \\n \\n    \\nTrims trailing blanks. If the argument contains a special character or mnemonic operator, \\nlisted below, use %QKTRIM. \\n\\nQKTRIM produces a result with the following special characters and mnemonic operators masked \\nso the macro processor interprets them as text instead of as elements of the macro language: \\n\\n  & % \' \\" ( ) + - * / < > = ¬ ? ~ ; , # blank AND OR NOT EQ NE LE LT GE GT IN \\n  \\nAutocall macros are included in a SAS library. This library might not be installed at your \\nsite or might be a site-specific version. If you cannot access this macro or if you want to \\nfind out if the library is a site-specific version, see your on-site SAS support personnel."},"%KVERIFY":{"help":"Syntax: %KVERIFY (source, excerpt) \\n\\nReturns the position of the first character unique to an expression. \\n\\nArguments:\\nsource \\n  is text or a text expression that you want to examine for characters that do not exist in excerpt. \\nexcerpt \\n  is text or a text expression that defines the set of characters that %KVERIFY uses to examine source."},"%ARMEND":{"help":"Indicates the termination of an application. \\n    \\nSyntax: %ARMEND< (option-1 <, ...option-n>)>; \\n\\nAvailable options are:\\n\\n  APPID=numeric variable or constant \\n  is the application ID to use on the ARM_GETID function call. The value must be a numeric \\n  variable or constant. \\n\\n  APPIDVAR=numeric variable \\n  is the application ID. The value must be a numeric variable.\\n\\n  LEVEL=numeric variable or constant \\n  is a variable that specifies the execution level. The value must be a numeric constant or variable.\\n\\n  MACONLY=NO | YES \\n  enables the %ARMEND macro to be issued in open code. You set the value to YES if the macro can be \\n  issued in open code, and NO if it can be issued only in a DATA step.\\n\\n  Default: NO \\n\\n  SCL=NO | YES \\n  is used only in SCL programs and specifies whether the macro is in an SCL environment. Set the value\\n  to YES if the macro is in an SCL environment, and NO if it is not. Default: NO"},"%ARMGTID":{"help":"Assigns a unique identifier to a transaction class. \\n    \\nSyntax: %ARMGTID (TXNNAME=\'transaction-name\' < option-1 <, ...option-n>>); \\n\\nUse the %ARMGTID macro to name a transaction class. Transaction classes are related \\nunits of work within an application. One or more %ARMGTID macros are typically issued \\nwhen the application starts to name each of the transaction classes used by the application. \\nThe %ARMGTID macro produces only one \\nrecord for each transaction class, even if there are multiple %ARMGTID macros for the \\nsame transaction class."},"%ARMINIT":{"help":"Signifies the initialization of an application. \\n    \\nSyntax: %ARMINIT (APPNAME=\'application-name\' <, option-1 <, ...option-n>>); \\n\\nAvailable options are:\\n\\n  APPIDVAR=numeric variable -- is the application ID. The value must be a numeric variable. \\n\\n  APPUSER=\'application-userID\' -- is the application user ID. The value is a SAS character variable or quoted literal. \\n\\n  GETID=NO | YES -- is optional and denotes whether to generate an ARM_GETID function call after ARM_INIT. Default: NO \\n\\n  LEVEL=numeric constant or variable -- is a variable that specifies the execution level. \\n\\n  MACONLY=NO | YES -- enables the %ARMINIT macro to be issued in open code. Default: NO \\n\\n  SCL=NO | YES -- is used only in SCL programs and specifies whether the macro is in an SCL environment. Default: NO \\n\\n  TXNIDVAR=numeric variable -- is a numeric variable that contains the value of the transaction ID. \\n\\n  TXNDET=\'name\' -- is a transaction detail. The value is a SAS character variable or quoted literal. \\n\\n  TXNNAME=\'transaction-name\' -- is the transaction name. The value is a SAS character variable or quoted literal value."},"%ARMSTOP":{"help":"Marks the end of a transaction instance. \\n    \\nSyntax: %ARMSTOP (<option1 <, ...option-n>>);\\n\\nAvailable options are:\\n\\n  LEVEL=numeric constant or variable \\n  is a variable that specifies the execution level. The value must be a numeric constant or variable.\\n\\n  MACONLY=NO | YES \\n  enables the %ARMSTOP macro to be issued in open code. You set the value to YES if the macro can be \\n  issued in open code, and NO if it can be issued only in a DATA step. \\n\\n  METRVAL1-7=\'name\' \\n  is the value of the user-defined metric. The value must be a SAS character variable or a quoted literal \\n  value up to eight characters in length.\\n\\n  SCL=NO | YES \\n  is used only in SCL programs and specifies whether the macro is in an SCL environment. Set the value \\n  to YES if the macro is in an SCL environment, and NO if it is not. Default: NO \\n\\n  SHANDLE=numeric variable or constant \\n  is the start handle to use on the ARM_UPDATE function call. The value must be a numeric variable or constant. \\n\\n  SHDLVAR=numeric variable \\n  is a numeric variable that contains the value of the start handle. \\n\\n  STATUS=numeric variable or numeric constant \\n  is a transaction status value to pass to the ARM_STOP function call. The value must be a numeric \\n  variable or numeric constant 0, 1, or 2. The default is 0."},"%ARMSTRT":{"help":"Signals the start of execution of a transaction instance and returns a unique handle that is passed \\nto %ARMUPDT and %ARMSTOP. \\n\\nSyntax: %ARMSTRT (option-1 <, ...option-n>); \\n\\nAvailable options are: \\n\\n  APPID=numeric variable or constant -- is the application ID to use on the ARM_GETID function call. \\n\\n  APPIDVAR=numeric variable -- is the application ID. The value must be a numeric variable.\\n\\n  CORR=n -- defines the type of parent and child transactions. Default: 0 \\n\\n  GETID=NO | YES -- is optional and denotes whether to generate an ARM_GETID function call before ARM_START. Default: NO \\n\\n  LEVEL=numeric constant or variable \\n  is a variable that specifies the execution level. The value must be a numeric constant or variable.\\n\\n  MACONLY=NO | YES -- enables the %ARMSTRT macro to be issued in open code. Default: NO \\n\\n  METRVAL1-7=\'name\' -- is the value of the user-defined metric. The value must be a SAS character variable or a quoted literal.  \\n\\n  PARNTVAR=numeric variable -- is a numeric variable that contains the value of the parent transaction start handle. \\n\\n  SCL=NO | YES -- is used only in SCL programs and specifies whether the macro is in an SCL environment. Default: NO \\n\\n  SHDLVAR=numeric variable -- is a numeric variable that contains the value of the start handle. \\n\\n  TXNDET=\'name\' -- is a transaction detail. The value is a SAS character variable or quoted literal.\\n\\n  TXNID=numeric variable or constant -- is the transaction ID to use in the ARM_START function call. \\n\\n  TXNIDVAR=numeric variable -- is a numeric variable that contains the value of the transaction ID when GETID=NO. . \\n\\n  TXNNAME=\'transaction-name\' -- is the transaction name. The value is a SAS character variable or quoted literal."},"%ARMUPDT":{"help":"Updates a transaction that has been previously started. \\n    \\nSyntax: %ARMUPDT (DATA=\'variable\', <option-1 <, ...option-n>>); \\n\\nwhere: \\n\\n  DATA=\'variable\' -- is a SAS character variable or a quoted literal from the user-supplied data buffer that \\n  contains text to pass to the ARM_UPDATE function call. DATA= is not required, but it is highly recommended. \\n\\n  LEVEL=numeric constant or variable \\n  is a variable that specifies the execution level. The value must be a numeric constant or variable.\\n\\n  MACONLY=NO | YES -- enables the %ARMUPDT macro to be issued in open code. Default: NO \\n\\n  METRVAL1-7=\'name\' \\n  is the value of the user-defined metric. The value must be a SAS character variable or a quoted literal. \\n\\n  SCL=NO | YES \\n  is used only in SCL programs and specifies whether the macro is in an SCL environment. Default: NO \\n\\n  SHANDLE=numeric or constant \\n  is the start handle to use on the ARM_UPDATE function call. The value must be a numeric or constant.\\n\\n  SHDLVAR=numeric variable -- is a numeric variable that contains the value of the start handle."},"%ARMCONV":{"help":"Converts a SAS System 9 or later ARM log written in simple format to the more readable \\nlabel=item ARM format used in Release 8.2."},"%ARMJOIN":{"help":"Reads the six SAS data sets created by the %ARMPROC macro and creates SAS data sets and \\nSQL views that contain common information about applications and transactions.\\n\\nSyntax: %ARMJOIN (<option-1 <, ...option-n>>); \\n\\nAvailable options are: \\n\\n  LIBIN=libref \\n  is the libref for the SAS library that contains the six SAS data sets that are created \\n  by the %ARMPROC macro. Default: WORK \\n\\n  LIBOUT=libref \\n  is the libref for the SAS library that contains the application and transaction data sets. \\n  Default: WORK \\n  Restriction: If a Read-only library is specified in the LIBOUT= option, an error message \\n  is written to the ARM log and processing is stopped. \\n\\n  TXNDS=YES | NO \\n  specifies whether the transaction data sets are to be created. Default: YES \\n\\n  UPDTDS=YES | NO \\n  specifies whether the update data sets are to be created. Default: YES"},"%ARMPROC":{"help":"Processes an input ARM log and outputs six SAS data sets that contain the gathered \\ninformation from the log. \\n    \\nSyntax: %ARMPROC (<option-1 <, ...option-n>>); \\n\\nAvailable options are:\\n\\n  LIB=libref \\n  is the libref for the SAS library that contains the six SAS data sets. Default: WORK \\n\\n  LOG=pathname \\n  is the pathname for the physical location of the ARM log. If a pathname is not specified, \\n  you must pre-assign the ARMLOG fileref before calling the macro.\\n\\n  LOGNEW=pathname \\n  is the pathname of the physical location of the new ARM log. It is used when ARM \\n  processing is resumed."},"%PERFEND":{"help":"Syntax: %PERFEND;\\n    \\nIndicates the termination of the application.\\n\\nUse the %PERFEND macro to terminate an application or user event. Each %PERFEND macro \\nis paired with one %PERFINIT macro to mark the end of an application. The %PERFEND means \\nthat the application does not issue any more ARM calls. ARM calls issued after an application \\nhas been terminated with the %PERFEND macro result in an error. All transaction class \\nidentifiers are cleared and are no longer available after the %PERFEND macro."},"%PERFINIT":{"help":"Names the application instance and initializes the ARM interface. \\n    \\nSyntax: %PERFINIT(APPNAME=\'application-name\'); \\n    \\nAPPNAME=\'application-name\'; \\nis the application name. The value is a SAS character variable or quoted literal. \\n\\nRestriction: The application name has a 127-character limit."},"%PERFSTOP":{"help":"Specifies the end of a transaction. \\n    \\nSyntax: %PERFSTOP; \\n\\nThere are no input parameters for the %PERFSTOP macro. \\n\\nUse the %PERFSTOP macro to signal the end of a transaction that was started using \\nthe %PERFSTRT macro. The %PERFSTOP macro contains default user metrics. To see the \\nrelationships between %PERFSTOP and the default user metrics, see Default User \\nMetrics and Performance Macros."},"%PERFSTRT":{"help":"Syntax: %PERFSTRT(TXNNAME=\'transaction-name\'); \\n    \\nUse the %PERFSTRT macro to signal the start of a transaction. The %PERFSTRT macro \\ncontains default user metrics. "}}}')}}]);